insert into hunt_spots (code, grp, title, description, position) values ('A1', 'Blackwater disposal', 'Disposal A1', 'The latrine pipe ends at the ground surface. Wastewater lies exposed on the soil.', 1);
insert into hunt_spots (code, grp, title, description, position) values ('A2', 'Blackwater disposal', 'Disposal A2', 'The latrine pipe goes straight into a ditch that drains the fields.', 2);
insert into hunt_spots (code, grp, title, description, position) values ('A3', 'Blackwater disposal', 'Disposal A3', 'A hole dug in the ground. No lining on the sides, no lid.', 3);
insert into hunt_spots (code, grp, title, description, position) values ('A4', 'Blackwater disposal', 'Disposal A4', 'A hole dug in the ground with a lid on top. The sides are not reinforced.', 4);
insert into hunt_spots (code, grp, title, description, position) values ('A5', 'Blackwater disposal', 'Disposal A5', 'A hole with block walls and a concrete cover. The base is not sealed: liquid soaks into the soil, solids are desludged.', 5);
insert into hunt_spots (code, grp, title, description, position) values ('A6', 'Blackwater disposal', 'Disposal A6', 'A container with two chambers. Solids settle, and an overflow pipe takes the effluent to a leach pit.', 6);
insert into hunt_spots (code, grp, title, description, position) values ('A7', 'Blackwater disposal', 'Disposal A7', 'A fully sealed container. Nothing leaks into the ground; it must be emptied by truck.', 7);
insert into hunt_spots (code, grp, title, description, position) values ('A8', 'Blackwater disposal', 'Disposal A8', 'The latrine is connected to the municipal sewer line.', 8);
insert into hunt_spots (code, grp, title, description, position) values ('B1', 'Water source', 'Source B1', 'Water arrives through pipes from the Water Establishment to a tap at the site entrance.', 9);
insert into hunt_spots (code, grp, title, description, position) values ('B2', 'Water source', 'Source B2', 'A drilled well with a concrete apron, capped and sealed for the first metres.', 10);
insert into hunt_spots (code, grp, title, description, position) values ('B3', 'Water source', 'Source B3', 'A dug well, open at the top, with no slab around it.', 11);
insert into hunt_spots (code, grp, title, description, position) values ('B4', 'Water source', 'Source B4', 'Water flows from the ground into a fenced spring box with a drainage channel.', 12);
insert into hunt_spots (code, grp, title, description, position) values ('B5', 'Water source', 'Source B5', 'Water flows out of the ground into an open pool used by animals too.', 13);
insert into hunt_spots (code, grp, title, description, position) values ('B6', 'Water source', 'Source B6', 'A truck fills the tanks twice a week; an NGO pays for it.', 14);
insert into hunt_spots (code, grp, title, description, position) values ('C1', 'Latrine', 'Latrine C1', 'Block walls, a door that locks from inside, a light, and a working pour-flush pan.', 15);
insert into hunt_spots (code, grp, title, description, position) values ('C2', 'Latrine', 'Latrine C2', 'Walls of plastic sheeting on a wooden frame. The pan works.', 16);
insert into hunt_spots (code, grp, title, description, position) values ('C3', 'Latrine', 'Latrine C3', 'Concrete walls and a door, but the pit has been blocked for months.', 17);
insert into hunt_spots (code, grp, title, description, position) values ('C4', 'Latrine', 'Latrine C4', 'Concrete walls and a lockable door; the door hinge needs a small repair.', 18);
